import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { doctorApi } from '../../api/doctorApi';
import Card from '../../components/Card';
import Loader from '../../components/Loader';
import ErrorBox from '../../components/ErrorBox';

const AppointmentDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [appointment, setAppointment] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchAppointment = async () => {
      try {
        const response = await doctorApi.getAppointmentDetails(id);
        if (response.success) {
          setAppointment(response.appointment);
        }
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to fetch appointment details');
      } finally {
        setLoading(false);
      }
    };

    fetchAppointment();
  }, [id]);

  if (loading) return <Loader />;

  if (error) {
    return (
      <div className="p-6 max-w-7xl mx-auto">
        <ErrorBox message={error} />
      </div>
    );
  }

  if (!appointment) {
    return (
      <div className="p-6 max-w-7xl mx-auto">
        <Card>
          <div className="text-center py-12">
            <p className="text-gray-600 text-lg">Appointment not found</p>
          </div>
        </Card>
      </div>
    );
  }

  const getStatusBadge = (status) => {
    const badges = {
      CONFIRMED: 'badge-info',
      PENDING: 'badge-warning',
      COMPLETED: 'badge-success',
      CANCELLED: 'badge-danger'
    };
    return badges[status] || 'badge-gray';
  };

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <button
        onClick={() => navigate('/doctor/dashboard')}
        className="mb-6 text-blue-600 hover:text-blue-700 flex items-center gap-2 font-medium"
      >
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
        </svg>
        Back to Dashboard
      </button>

      <div className="mb-8 fade-in">
        <h1 className="text-4xl font-bold text-gray-800 mb-2">Appointment Details</h1>
        <p className="text-gray-600 text-lg">View patient information and appointment details</p>
      </div>
      
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <Card className="border-2 border-blue-200">
          <div className="flex items-center gap-4 mb-6">
            <div className="w-16 h-16 bg-gradient-to-br from-green-500 to-emerald-600 rounded-full flex items-center justify-center">
              <span className="text-white font-bold text-xl">
                {appointment.patient?.user?.name?.charAt(0) || 'P'}
              </span>
            </div>
            <div>
              <h2 className="text-2xl font-bold text-gray-800">Patient Information</h2>
              <p className="text-gray-600">{appointment.patient?.user?.name || 'N/A'}</p>
            </div>
          </div>
          <div className="space-y-4">
            <div className="flex items-center gap-3">
              <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 12a4 4 0 10-8 0 4 4 0 008 0zm0 0v1.5a2.5 2.5 0 005 0V12a9 9 0 10-9 9m4.5-1.206a8.959 8.959 0 01-4.5 1.207" />
              </svg>
              <div>
                <p className="text-gray-500 text-xs">Email</p>
                <p className="font-semibold text-gray-800">{appointment.patient?.user?.email || 'N/A'}</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" />
              </svg>
              <div>
                <p className="text-gray-500 text-xs">Phone</p>
                <p className="font-semibold text-gray-800">{appointment.patient?.user?.phone || 'N/A'}</p>
              </div>
            </div>
            {appointment.patient?.dateOfBirth && (
              <div className="flex items-center gap-3">
                <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                </svg>
                <div>
                  <p className="text-gray-500 text-xs">Date of Birth</p>
                  <p className="font-semibold text-gray-800">
                    {new Date(appointment.patient.dateOfBirth).toLocaleDateString()}
                  </p>
                </div>
              </div>
            )}
            {appointment.patient?.gender && (
              <div className="flex items-center gap-3">
                <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
                <div>
                  <p className="text-gray-500 text-xs">Gender</p>
                  <p className="font-semibold text-gray-800">{appointment.patient.gender}</p>
                </div>
              </div>
            )}
            {appointment.patient?.address && (
              <div className="flex items-start gap-3">
                <svg className="w-5 h-5 text-blue-600 mt-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                </svg>
                <div>
                  <p className="text-gray-500 text-xs">Address</p>
                  <p className="font-semibold text-gray-800">{appointment.patient.address}</p>
                </div>
              </div>
            )}
          </div>
        </Card>

        <Card className="border-2 border-indigo-200">
          <div className="flex items-center gap-4 mb-6">
            <div className="w-16 h-16 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-full flex items-center justify-center">
              <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <div>
              <h2 className="text-2xl font-bold text-gray-800">Appointment Details</h2>
              <span className={`badge ${getStatusBadge(appointment.status)} mt-1`}>
                {appointment.status}
              </span>
            </div>
          </div>
          <div className="space-y-4">
            <div className="flex items-center gap-3">
              <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
              <div>
                <p className="text-gray-500 text-xs">Date</p>
                <p className="font-semibold text-gray-800">
                  {new Date(appointment.appointmentDate).toLocaleDateString('en-US', { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <div>
                <p className="text-gray-500 text-xs">Time</p>
                <p className="font-semibold text-gray-800">
                  {appointment.slotTime?.startTime} - {appointment.slotTime?.endTime}
                </p>
              </div>
            </div>
            <div className="flex items-start gap-3">
              <svg className="w-5 h-5 text-indigo-600 mt-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              <div>
                <p className="text-gray-500 text-xs">Reason</p>
                <p className="font-semibold text-gray-800">{appointment.reason}</p>
              </div>
            </div>
            {appointment.notes && (
              <div className="flex items-start gap-3">
                <svg className="w-5 h-5 text-indigo-600 mt-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                </svg>
                <div>
                  <p className="text-gray-500 text-xs">Notes</p>
                  <p className="font-semibold text-gray-800">{appointment.notes}</p>
                </div>
              </div>
            )}
          </div>
        </Card>
      </div>

      {appointment.status !== 'CANCELLED' && appointment.status !== 'COMPLETED' && (
        <Card className="border-2 border-green-200 bg-gradient-to-r from-green-50 to-emerald-50">
          <div className="text-center py-6">
            <div className="mb-4">
              <svg className="w-16 h-16 text-green-600 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
            </div>
            <h3 className="text-xl font-bold text-gray-800 mb-2">Create Prescription</h3>
            <p className="text-gray-600 mb-6">
              Create a QR-based prescription that will be automatically emailed to the patient
            </p>
            <button
              onClick={() => navigate(`/doctor/prescription/${appointment._id}`)}
              className="btn btn-secondary px-8 py-3 text-lg font-semibold flex items-center gap-2 mx-auto"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
              </svg>
              Create QR Prescription
            </button>
            <p className="text-sm text-gray-500 mt-4">
              📧 Prescription will be sent via email with QR code and PDF attachment
            </p>
          </div>
        </Card>
      )}
      
      {appointment.status === 'COMPLETED' && (
        <Card className="border-2 border-green-200 bg-green-50">
          <div className="text-center py-6">
            <svg className="w-16 h-16 text-green-600 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <p className="text-green-700 font-semibold text-lg">
              Appointment completed. Prescription has been sent to patient via email.
            </p>
          </div>
        </Card>
      )}
    </div>
  );
};

export default AppointmentDetails;
